def match(orders):
    buy_book = []
    sell_book = []
    order_map = {}
    trades = []

    for order in orders:
        if order[0] == 'limit':
            _, order_id, side, price, qty = order
            if side == 'buy':
                remaining = _match_against_book(order_id, price, qty, sell_book, True, trades)
                if remaining > 0:
                    buy_book.append((price, len(order_map), order_id, remaining))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    order_map[order_id] = ('buy', len(buy_book) - 1)
            else:
                remaining = _match_against_book(order_id, price, qty, buy_book, False, trades)
                if remaining > 0:
                    sell_book.append((price, len(order_map), order_id, remaining))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    order_map[order_id] = ('sell', len(sell_book) - 1)
            order_map[order_id] = (order_map.get(order_id, ('buy' if side == 'buy' else 'sell', -1))[0], 
                                   order_map.get(order_id, ('buy' if side == 'buy' else 'sell', -1))[1])

        elif order[0] == 'ioc':
            _, order_id, side, price, qty = order
            if side == 'buy':
                _match_against_book(order_id, price, qty, sell_book, True, trades)
            else:
                _match_against_book(order_id, price, qty, buy_book, False, trades)

        elif order[0] == 'market':
            _, order_id, side, qty = order
            if side == 'buy':
                _match_against_book(order_id, float('inf'), qty, sell_book, True, trades)
            else:
                _match_against_book(order_id, 0, qty, buy_book, False, trades)

        elif order[0] == 'cancel':
            _, order_id = order
            if order_id in order_map:
                side, _ = order_map[order_id]
                if side == 'buy':
                    buy_book[:] = [o for o in buy_book if o[2] != order_id]
                else:
                    sell_book[:] = [o for o in sell_book if o[2] != order_id]
                del order_map[order_id]

    return trades

def _match_against_book(incoming_id, price, qty, book, is_buy, trades):
    remaining = qty
    indices_to_remove = []

    for i, (resting_price, arrival_time, resting_id, resting_qty) in enumerate(book):
        if remaining == 0:
            break

        if is_buy and resting_price > price:
            break
        if not is_buy and resting_price < price:
            break

        trade_qty = min(remaining, resting_qty)

        if is_buy:
            trades.append([incoming_id, resting_id, resting_price, trade_qty])
        else:
            trades.append([resting_id, incoming_id, resting_price, trade_qty])

        remaining -= trade_qty

        if resting_qty == trade_qty:
            indices_to_remove.append(i)
        else:
            book[i] = (resting_price, arrival_time, resting_id, resting_qty - trade_qty)

    for i in reversed(indices_to_remove):
        book.pop(i)

    return remaining

